import { type LucideIcon } from "lucide-react";

// ── User / Auth ──────────────────────────────────────────────

export interface UserProfile {
  id: string;
  email: string;
  full_name: string;
  company_name: string | null;
  website_url: string | null;
  avatar_url: string | null;
  plan: PlanType;
  scans_used: number;
  scan_limit: number;
  created_at: string;
  billing_cycle_end: string;
}

export type PlanType = "free" | "pro" | "agency";

// ── Scans ────────────────────────────────────────────────────

export type ScanStatus = "pending" | "analyzing" | "completed" | "failed";

export type PageType =
  | "landing"
  | "product"
  | "homepage"
  | "pricing"
  | "signup"
  | "blog"
  | "other";

export interface Scan {
  id: string;
  user_id: string;
  url: string;
  favicon_url: string | null;
  page_title: string | null;
  page_type: PageType;
  status: ScanStatus;
  overall_score: number | null;
  issues_found: number;
  critical_issues: number;
  warnings: number;
  quick_wins: number;
  screenshot_url: string | null;
  device: "desktop" | "mobile" | "both";
  created_at: string;
  completed_at: string | null;
}

// ── CRO Pillars ──────────────────────────────────────────────

export type CroPillar =
  | "value_proposition"
  | "cta_effectiveness"
  | "trust_signals"
  | "visual_hierarchy"
  | "mobile_experience"
  | "content_copy"
  | "page_performance";

export type Severity = "critical" | "warning" | "info" | "passed";
export type Effort = "quick" | "moderate" | "significant";

export interface Finding {
  id: string;
  title: string;
  severity: Severity;
  current_state: string;
  recommendation: string;
  ai_suggestion: string;
  is_premium: boolean;
  effort: Effort;
  estimated_lift: string; // e.g. "1-3% conversion lift"
  category: string; // e.g. "Copy", "Design", "Technical"
}

export interface PillarResult {
  id: string;
  scan_id: string;
  pillar: CroPillar;
  score: number;
  weight: number; // pillar weight in overall score (0-1)
  benchmark: number; // industry average for this pillar
  findings: Finding[];
}

// ── Pricing ──────────────────────────────────────────────────

export interface PricingFeature {
  text: string;
  included: boolean;
  tooltip?: string;
}

export interface PricingTier {
  name: string;
  plan: PlanType;
  price_monthly: number;
  price_annual: number;
  subtitle: string;
  features: PricingFeature[];
  highlighted: boolean;
  cta_text: string;
  limits: string; // e.g. "50 scans/mo"
}

// ── CRO Pillar Config ────────────────────────────────────────

export interface CroPillarConfig {
  key: CroPillar;
  label: string;
  icon: LucideIcon;
  description: string;
  weight: number;
}

// ── Dashboard Stats ──────────────────────────────────────────

export interface DashboardStats {
  total_scans: number;
  avg_score: number;
  total_issues: number;
  critical_issues: number;
  estimated_revenue_impact: number;
  score_trend: number;
  scans_trend: number;
  quick_wins: number;
}

// ── Scan Step (for progress timeline) ────────────────────────

export interface ScanStep {
  label: string;
  description: string;
}

